#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
int main(void) {
    int x = 5;
    if (fork() == 0) { x = 10; exit(0); }
    wait(NULL);
    printf("%d\n", x);
    return 0;
}

#include <pthread.h>
#include <stdio.h>
int counter = 0;
void *work(void *arg) { counter = 10; return NULL; }
int main(void) {
    pthread_t t;
    pthread_create(&t, NULL, work, NULL);
    pthread_join(t, NULL);
    printf("%d\n", counter);
    return 0;
}

#include <stdio.h>
#include <unistd.h>
#include <sys/wait.h>
int x = 1;
int main(void) {
    if (fork() == 0) x = 2;
    else wait(NULL);
    printf("%d %p\n", x, (void *)&x);
    return 0;
}
